return {["fb29_01"]={["down"]=[[fb29_03]],["dsc"]=[[这是一户普通的农家，屋里没有什么像样的摆设。墙边摆放着一些农具，除此之外四壁皆空，看来并不富裕。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb29_01]],["name"]=[[民居]],["permission"]=2,["role1"]=[[fb29r01_1]],["role2"]=[[fb29r01_2]],["stepMusic"]=[[jiaobu]]},["fb29_02"]={["dsc"]=[[这是一个简陋的灶房，四壁都被烟火熏的黑糊糊的，灶台旁的墙上贴着一张发黄的黄裱纸，旁边挂着一些风干的兽肉。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb29_02]],["name"]=[[灶房]],["permission"]=2,["right"]=[[fb29_03]],["role1"]=[[fb29r02_1]],["stepMusic"]=[[jiaobu]]},["fb29_03"]={["down"]=[[fb29_10]],["dsc"]=[[这是一户普通的农家，屋里没有什么像样的摆设。墙边摆放着一些农具，除此之外四壁皆空，看来并不富裕。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb29_03]],["left"]=[[fb29_02]],["name"]=[[民居]],["permission"]=2,["role1"]=[[fb29r03_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb29_01]]},["fb29_04"]={["dsc"]=[[从这里往西走，可达延平白猿洞，往东可达桃花江。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb29_04]],["name"]=[[延平小路]],["permission"]=2,["right"]=[[fb29_05]],["role1"]=[[fb29r04_1]],["role2"]=[[fb29r04_2]],["role3"]=[[fb29r04_3]],["stepMusic"]=[[jiaobu]]},["fb29_05"]={["down"]=[[fb29_13]],["dsc"]=[[这里是桃花江边，江水清澈，水流平缓，两岸都是无边的桃树，不断有桃花随风飘入江中，随波逐流。江边停泊着一条渔船。旁边还有一条万灵谷的快船。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb29_05]],["item1"]=[[fb29item17]],["left"]=[[fb29_04]],["name"]=[[桃花江]],["permission"]=2,["right"]=[[fb29_06]],["stepMusic"]=[[jiaobu]]},["fb29_06"]={["down"]=[[fb29_66]],["dsc"]=[[这里是桃花江边的一个小村，村口有几个农家的小孩正在大树底下玩耍。远远的升起缕缕炊烟，忙碌了一天的人们开始做饭了。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb29_06]],["item1"]=[[bfitem1]],["left"]=[[fb29_05]],["name"]=[[小村口]],["permission"]=2,["right"]=[[fb29_07]],["role1"]=[[fb29r06_1]],["role2"]=[[fb29r06_2]],["stepMusic"]=[[jiaobu]]},["fb29_07"]={["dsc"]=[[走在小村的石板路上，两旁都是用青石砌成的房屋。村子里静悄悄的，看不到行人，偶尔传来一两声狗叫。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb29_07]],["item1"]=[[bfitem2]],["left"]=[[fb29_06]],["name"]=[[小村]],["permission"]=2,["right"]=[[fb29_08]],["stepMusic"]=[[jiaobu]]},["fb29_08"]={["dsc"]=[[走在小村的石板路上，两旁都是用青石砌成的房屋。村子里静悄悄的，看不到行人，偶尔传来一两声狗叫。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb29_08]],["left"]=[[fb29_07]],["name"]=[[小村]],["permission"]=2,["right"]=[[fb29_09]],["role1"]=[[fb29r08_1]],["stepMusic"]=[[jiaobu]]},["fb29_09"]={["dsc"]=[[走在小村的石板路上，两旁都是用青石砌成的房屋。村子里静悄悄的，看不到行人，偶尔传来一两声狗叫。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb29_09]],["left"]=[[fb29_08]],["name"]=[[小村]],["permission"]=2,["right"]=[[fb29_10]],["stepMusic"]=[[jiaobu]]},["fb29_10"]={["down"]=[[fb29_14]],["dsc"]=[[走在小村的石板路上，两旁都是用青石砌成的房屋。村子里静悄悄的，看不到行人，偶尔传来一两声狗叫。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb29_10]],["left"]=[[fb29_09]],["name"]=[[小村]],["permission"]=2,["right"]=[[fb29_11]],["stepMusic"]=[[jiaobu]],["up"]=[[fb29_03]]},["fb29_11"]={["down"]=[[fb29_15]],["dsc"]=[[走在小村的石板路上，两旁都是用青石砌成的房屋。东边有一座学堂，里面传来朗朗的读书声。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb29_11]],["left"]=[[fb29_10]],["name"]=[[小村]],["permission"]=2,["right"]=[[fb29_12]],["stepMusic"]=[[jiaobu]]},["fb29_12"]={["dsc"]=[[这里是一座简陋的学堂，似乎是用祠堂改成的，正中供桌上还供着一些牌位，上面落满了灰尘。几个八、九岁的农家小孩正跟着先生在念书。]],["id"]=[[fb29_12]],["left"]=[[fb29_11]],["name"]=[[学堂]],["permission"]=2,["role1"]=[[fb29r12_1]],["role2"]=[[fb29r12_2]],["role3"]=[[fb29r12_3]],["stepMusic"]=[[jiaobu]]},["fb29_13"]={["down"]=[[fb29_18]],["dsc"]=[[这里是桃花江边，江水清澈，水流平缓，两岸都是无边的桃树，不断有桃花随风飘入江中，随波逐流。江边停泊着一条渔船。旁边还有一条万灵谷的快船。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb29_13]],["item1"]=[[2019qxhdd1]],["name"]=[[东岸]],["permission"]=2,["role1"]=[[fb29r13_100]],["role2"]=[[fb29r13_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb29_05]]},["fb29_14"]={["down"]=[[fb29_19]],["dsc"]=[[走在小村的石板路上，两旁都是用青石砌成的房屋。村子里静悄悄的，看不到行人，偶尔传来一两声狗叫。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb29_14]],["name"]=[[小村]],["permission"]=2,["role1"]=[[fb29r14_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb29_10]]},["fb29_15"]={["dsc"]=[[这里是小村的东头。因为暴雨刚过，地上一片泥泞，路非常不好走。顺着这条路一直向东走一两个时辰就可到武夷山了。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb29_15]],["name"]=[[村东口]],["permission"]=2,["right"]=[[fb29_16]],["stepMusic"]=[[jiaobu]],["up"]=[[fb29_11]]},["fb29_16"]={["dsc"]=[[你到了一片竹林，往东走可以到达武夷山，往西走可以到村东口。]],["fightBackground"]=[[森林内]],["id"]=[[fb29_16]],["item1"]=[[fb29item15]],["left"]=[[fb29_15]],["name"]=[[竹林深处]],["permission"]=2,["right"]=[[fb29_17]],["stepMusic"]=[[jiaobu]]},["fb29_17"]={["dsc"]=[[这是两峰夹缝中的一条小路。路面是丹崖石板铺就的，两边都是高耸的山峰。路边有条数尺宽的小沟，沟里终年流动着清澈的泉水，水中时而闪现寸许长的游鱼。]],["fightBackground"]=[[山外]],["id"]=[[fb29_17]],["left"]=[[fb29_16]],["name"]=[[武夷山山路]],["permission"]=2,["role1"]=[[fb29r17_1]],["stepMusic"]=[[jiaobu]]},["fb29_18"]={["down"]=[[fb29_21]],["dsc"]=[[这里是桃花江边的一条泥土小路，一旁就是清澈的江水。夹岸连绵不断的桃花灿若云霞，暗香袭人，引来许多蜜蜂在花树间飞舞。]],["id"]=[[fb29_18]],["name"]=[[江边小路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb29_13]]},["fb29_19"]={["dsc"]=[[这是一户普通的农家，屋里没有什么像样的摆设。墙边摆放着一些农具，除此之外四壁皆空，看来并不富裕。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb29_19]],["name"]=[[民居]],["permission"]=2,["right"]=[[fb29_20]],["role1"]=[[fb29r19_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb29_14]]},["fb29_20"]={["dsc"]=[[这是一个用篱笆围成的简易院落，远处种着几畦蔬菜。院子中间一棵高大的柿树上结满了鲜红的果实，旁边的地上盖着一张厚厚的草席。]],["id"]=[[fb29_20]],["item1"]=[[fb29item18]],["left"]=[[fb29_19]],["name"]=[[后院]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb29_21"]={["down"]=[[fb29_24]],["dsc"]=[[这里是桃花江边的一条泥土小路，一旁就是清澈的江水。夹岸连绵不断的桃花灿若云霞，暗香袭人，引来许多蜜蜂在花树间飞舞。]],["id"]=[[fb29_21]],["name"]=[[江边小路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb29_18]]},["fb29_22"]={["down"]=[[fb29_34]],["dsc"]=[[这里是万灵谷的厨房，平常弟子们饿了可以到这里要些食物。房中灶火正旺，一个大厨师正忙的满头大汗。屋角放着一个大水缸。]],["id"]=[[fb29_22]],["item1"]=[[fb29item104]],["name"]=[[厨房]],["permission"]=2,["role1"]=[[fb23r22_1]],["stepMusic"]=[[jiaobu]]},["fb29_23"]={["dsc"]=[[此处往西可到昆明青石路，往东可到江边小路。]],["fightBackground"]=[[山外]],["id"]=[[fb29_23]],["name"]=[[昆明山路]],["permission"]=1,["right"]=[[fb29_24]],["stepMusic"]=[[jiaobu]]},["fb29_24"]={["dsc"]=[[这里是桃花江边的一条泥土小路，一旁就是清澈的江水。夹岸连绵不断的桃花灿若云霞，暗香袭人，引来许多蜜蜂在花树间飞舞。]],["id"]=[[fb29_24]],["item1"]=[[fb29item7]],["left"]=[[fb29_23]],["name"]=[[江边小路]],["permission"]=1,["rightDown"]=[[fb29_30]],["role1"]=[[fb29r24_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb29_21]]},["fb29_25"]={["dsc"]=[[这里是北院，院子里静悄悄的。北面有一个厨房，远远飘来一股饭香，想是该开饭了。]],["id"]=[[fb29_25]],["name"]=[[北院]],["permission"]=2,["right"]=[[fb29_26]],["role1"]=[[fb29r25_100]],["role2"]=[[fb29r25_101]],["stepMusic"]=[[jiaobu]]},["fb29_26"]={["down"]=[[fb29_36]],["dsc"]=[[这里是万灵谷存放武器的地方，四面靠墙全是兵器架，上面插满了各种兵器。]],["id"]=[[fb29_26]],["left"]=[[fb29_25]],["name"]=[[兵器房]],["permission"]=2,["role1"]=[[fb29r26_1]],["stepMusic"]=[[jiaobu]]},["fb29_27"]={["down"]=[[fb29_37]],["dsc"]=[[这里是教主平时看书的地方，房间不大，只靠窗摆着一张书案，案边放了几本书，看来是教主经常翻看的。]],["id"]=[[fb29_27]],["item1"]=[[fb29item8]],["item2"]=[[fb29item11]],["item3"]=[[fb29item106]],["name"]=[[书房]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb29_28"]={["down"]=[[fb29_38]],["dsc"]=[[这里是个花园，一年四季都生长着各种奇异的花草，在阳光下发出七彩妖艳的光辉。花园里一片沉寂，竟看不到一只蜜蜂或蝴蝶飞舞。旁边有一座小亭子。]],["id"]=[[fb29_28]],["name"]=[[花园]],["permission"]=2,["right"]=[[fb29_29]],["role1"]=[[fb29r28_1]],["stepMusic"]=[[jiaobu]]},["fb29_29"]={["dsc"]=[[这里是一个花园中的小亭子，雕梁画栋，古色古香。壁上挂着一幅《少女月下舞剑图》。]],["id"]=[[fb29_29]],["item1"]=[[fb29item20]],["left"]=[[fb29_28]],["name"]=[[腾蛟亭]],["permission"]=2,["role1"]=[[fb29r29_1]],["stepMusic"]=[[jiaobu]]},["fb29_30"]={["down"]=[[fb29_40]],["dsc"]=[[你走在两山相夹的峡谷中，山上山下全是无边的野桃树，一阵山风吹来，落英缤纷。数百年落下的桃花，桃枝都堆积在地上，人走在上面软软的。]],["id"]=[[fb29_30]],["item1"]=[[fb29item105]],["leftUp"]=[[fb29_24]],["name"]=[[桃花峪]],["permission"]=1,["right"]=[[fb29_31]],["role1"]=[[fb29r30_101]],["stepMusic"]=[[jiaobu]]},["fb29_31"]={["dsc"]=[[这里是万灵谷中的山间小路，蜿蜒曲折盘旋而上。你顺手拨开伸向路中的枝条，树枝忽然一动，缩了回去，“哇...”竟然是一条形似枯枝的毒蛇。]],["fightBackground"]=[[山内]],["id"]=[[fb29_31]],["left"]=[[fb29_30]],["name"]=[[万灵山路]],["permission"]=2,["right"]=[[fb29_32]],["stepMusic"]=[[jiaobu]]},["fb29_32"]={["down"]=[[fb29_42]],["dsc"]=[[这里是万灵谷中的山间小路，蜿蜒曲折盘旋而上。你顺手拨开伸向路中的枝条，树枝忽然一动，缩了回去，“哇...”竟然是一条形似枯枝的毒蛇。]],["fightBackground"]=[[山内]],["id"]=[[fb29_32]],["item1"]=[[fb29item6]],["left"]=[[fb29_31]],["name"]=[[万灵山路]],["permission"]=2,["right"]=[[fb29_33]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]]},["fb29_33"]={["dsc"]=[[这里是万灵谷中的山间小路，蜿蜒曲折盘旋而上。你顺手拨开伸向路中的枝条，树枝忽然一动，缩了回去，“哇...”竟然是一条形似枯枝的毒蛇。]],["f