]],["name"]=[[万灵山路]],["permission"]=1,["role1"]=[[fb29r40_1]],["role2"]=[[fb29r40_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb29_30]]},["fb29_41"]={["down"]=[[fb29_50]],["dsc"]=[[这里是一个天然形成的石洞，里面深邃广大。洞顶悬挂着许多钟乳石，不时传来几声滴答的水声。走在洞中，洞内阴暗潮湿，身旁忽然传来一阵“咝咝”的声音。]],["id"]=[[fb29_41]],["name"]=[[千毒窟]],["permission"]=2,["role1"]=[[fb29r41_1]],["role2"]=[[fb29r41_2]],["stepMusic"]=[[jiaobu]]},["fb29_42"]={["down"]=[[fb29_51]],["dsc"]=[[这里是万灵谷中的山间小路，蜿蜒曲折盘旋而上。你顺手拨开伸向路中的枝条，树枝忽然一动，缩了回去，“哇...”竟然是一条形似枯枝的毒蛇。]],["fightBackground"]=[[山内]],["id"]=[[fb29_42]],["name"]=[[万灵山路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb29_32]]},["fb29_43"]={["dsc"]=[[这是一间乱糟糟的厢房，里面到处都是各种大大小小的笼子、瓦罐之类的东西。不时能看到有毒虫在笼子里面上窜下跳，四处游走。]],["id"]=[[fb29_43]],["item1"]=[[fb29item21]],["item2"]=[[fb29item29]],["item3"]=[[fb29item102]],["name"]=[[厢房]],["permission"]=2,["right"]=[[fb29_44]],["stepMusic"]=[[jiaobu]]},["fb29_44"]={["down"]=[[fb29_52]],["dsc"]=[[这里是南跨院，院子里有棵很大的榕树，将天空大部遮住，院子里静悄悄的，只有几只高大的藏獒在树下来回踱步。]],["id"]=[[fb29_44]],["item1"]=[[fb29item23]],["left"]=[[fb29_43]],["name"]=[[南院]],["permission"]=2,["right"]=[[fb29_45]],["stepMusic"]=[[jiaobu]],["up"]=[[fb29_34]]},["fb29_45"]={["dsc"]=[[这里是万灵谷存放药品的地方，只见十多个黑漆木柜一字排开，上面开着数百个的小抽屉，每个抽屉上面都整整齐齐的贴着一行标签。]],["id"]=[[fb29_45]],["item1"]=[[fb29item22]],["item2"]=[[fb29item29]],["left"]=[[fb29_44]],["name"]=[[药室]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb29_46"]={["dsc"]=[[这是一个昏暗的房间，除了几张床之外什么都没有。室内光线昏暗，你不由的打了一个哈欠。]],["id"]=[[fb29_46]],["name"]=[[静室]],["permission"]=2,["role1"]=[[fb29r46_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb29_37]]},["fb29_47"]={["dsc"]=[[这里是个花园，一年四季都生长着各种奇异的花草，在阳光下发出七彩妖艳的光辉。花园里一片沉寂，竟看不到一只蜜蜂或蝴蝶飞舞。旁边有一座小亭子。]],["id"]=[[fb29_47]],["name"]=[[花园]],["permission"]=2,["right"]=[[fb29_48]],["role1"]=[[fb29r47_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb29_38]]},["fb29_48"]={["dsc"]=[[这里是一个花园中的小亭子，雕梁画栋，古色古香。亭子当中立着几个木人。]],["id"]=[[fb29_48]],["item1"]=[[fb29item4]],["left"]=[[fb29_47]],["name"]=[[栖凤亭]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb29_49"]={["down